describe('Dropdown Selection Test - The Internet', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/dropdown');
  });

  it('should display disabled prompt and allow selection of an option', () => {
    // Verify initial state: disabled prompt is visible
    cy.get('[data-testid="dropdown"]').should('be.visible');
    cy.get('[data-testid="dropdown-value"]').should('contain', 'Please select an option');

    // Intercept the API call to get dropdown options
    cy.intercept('GET', '/api/dropdown-options').as('getDropdownOptions');

    // Verify dropdown is disabled
    cy.get('[data-testid="dropdown-value"]').should('have.class', 'disabled');

    // Click on the dropdown to open it
    cy.get('[data-testid="dropdown-trigger"]').click();

    // Verify dropdown is now visible
    cy.get('[data-testid="dropdown"]').should('be.visible');

    // Verify prompt is gone
    cy.get('[data-testid="dropdown-value"]').should('not.contain', 'Please select an option');

    // Verify options are displayed
    cy.get('[data-testid="dropdown-option"]').should('be.visible');
    cy.get('[data-testid="dropdown-option"]').should('have.length.greaterThan', 0);

    // Select 'Option 2'
    cy.get('[data-testid="dropdown-option"]').eq(1).click();

    // Verify value is set to '2'
    cy.get('[data-testid="dropdown-value"]').should('contain', '2');

    // Verify 'Option 2' is now selected
    cy.get('[data-testid="dropdown-option"]').eq(1).should('have.class', 'selected');

    // Verify disabled prompt is gone
    cy.get('[data-testid="dropdown-value"]').should('not.contain', 'Please select an option');
  });

  it('should handle edge case when selecting disabled option', () => {
    // Verify initial state: disabled prompt is visible
    cy.get('[data-testid="dropdown"]').should('be.visible');
    cy.get('[data-testid="dropdown-value"]').should('contain', 'Please select an option');

    // Intercept the API call to get dropdown options
    cy.intercept('GET', '/api/dropdown-options').as('getDropdownOptions');

    // Open dropdown
    cy.get('[data-testid="dropdown-trigger"]').click();

    // Verify dropdown is visible
    cy.get('[data-testid="dropdown"]').should('be.visible');

    // Verify prompt is gone
    cy.get('[data-testid="dropdown-value"]').should('not.contain', 'Please select an option');

    // Verify options are displayed
    cy.get('[data-testid="dropdown-option"]').should('be.visible');

    // Attempt to select a disabled option (e.g., 'Option 3')
    cy.get('[data-testid="dropdown-option"]').eq(2).click();

    // Verify disabled prompt reappears
    cy.get('[data-testid="dropdown-value"]').should('contain', 'Please select an option');

    // Verify no value is set
    cy.get('[data-testid="dropdown-value"]').should('not.contain', '2');

    // Verify disabled option is not selected
    cy.get('[data-testid="dropdown-option"]').eq(2).should('not.have.class', 'selected');
  });
});
